import type { FeelCheck, Plan } from './types'

// Every line TIDE says during a session. All of it is generated by Sonic ahead of time
// (voiceLines(plan) during the paced-breathing check), so nothing waits on the network once
// the user's eyes are closed. Wellness wording only: no medical or diagnostic claims.

export const LINES = {
  intro: 'Close your eyes. Let your breath settle on its own.',
  cue: 'Come back to your breath.',
  question: 'Focused, or drifting?',
  caught: 'You caught it.',
  miss: 'Thanks. Keep noticing.',
  quiet: "That's okay. Back to the breath.",
  unclear: 'No problem. Back to the breath.',
  closing: "That's the end of your session. When you're ready, gently open your eyes.",
}

/** What TIDE says after a Feel Check, so the user hears the result with their eyes still closed. */
export function feedbackLine(fc: Pick<FeelCheck, 'answer' | 'match'>): string {
  if (fc.answer === 'none') return LINES.quiet
  if (fc.answer === 'unsure') return LINES.unclear
  return fc.match ? LINES.caught : LINES.miss
}

/** All lines a session from this plan can say. */
export function voiceLines(plan: Plan): string[] {
  return [
    plan.intro || LINES.intro,
    ...(plan.cues ?? []).map((c) => c.text),
    ...Object.values(LINES),
  ]
}
